function UNIT:IsClient()

    if _DATABASE.CLIENTS[self.UnitName] then
        return true
    end

    return false
end

--- Get the CLIENT of the unit  
-- @param #UNIT self
-- @return Wrapper.Client#CLIENT  
function UNIT:GetClient()

    local client = _DATABASE.CLIENTS[self.UnitName]

    if client then
