  -- Use default TZC if no transport zone combo is provided.
  TransportZoneCombo=TransportZoneCombo or self.tzcDefault
  
  local formation=TransportZoneCombo.PickupFormation or self:_GetFormationDefault(OpsGroup)

  return formation
end

